using UnityEditor;using UnityEngine;using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine.XR.Interaction.Toolkit;using UnityEngine.XR.Interaction.Toolkit.Interactors;using UnityEngine.XR.Interaction.Toolkit.Interactors.Casters;using UnityEngine.XR.Interaction.Toolkit.Inputs.Readers;
namespace DiwaliGameplay {
public static class AxisFocusQA {
 static List<object> rows=new List<object>();static NearFarInteractor hand;static string path=>Path.GetFullPath("../Game_Plans/Axis_Layout_Focused_2026-10-21.json");
 static void Save(string state){File.WriteAllText(path,Newtonsoft.Json.JsonConvert.SerializeObject(new{state,scope="Focused changed behaviours only; synthetic queued grip, actual transforms, player-height rendered views. No headset validation.",results=rows},Newtonsoft.Json.Formatting.Indented));}
 static void Check(string name,bool pass,string detail=""){rows.Add(new{name,pass,detail});Save("running");}
 static async Task<bool> Grip(GrabbableItem item){hand.selectInput.QueueManualState(false,0);await Task.Delay(120);foreach(var dir in new[]{Vector3.forward,Vector3.back,Vector3.left,Vector3.right,Vector3.up}){var col=item.grab.colliders.First(x=>x&&x.enabled);hand.transform.SetPositionAndRotation(col.bounds.center+dir*.5f,Quaternion.LookRotation(-dir));await Task.Delay(120);var targets=new List<UnityEngine.XR.Interaction.Toolkit.Interactables.IXRInteractable>();hand.GetValidTargets(targets);if(targets.Contains(item.grab)){hand.selectInput.QueueManualState(true,1);await Task.Delay(250);return item.IsHeld;}}return false;}
 static async Task Release(){hand.selectInput.QueueManualState(false,0);await Task.Delay(200);}
 static async Task Plunge(FireworksGame f,int expected){bool held=await Grip(f.plunger);Check("Plunger actual queued grip "+expected,held);if(held){var pos=hand.transform.position;for(int i=1;i<=10;i++){hand.transform.position=pos-Vector3.up*(i*.03f);await Task.Delay(35);}await Task.Delay(250);}Check("Physical plunger advances station "+expected,f.stage==expected,"stage="+f.stage);await Release();}
 [MenuItem("Diwali/Gameplay/Run focused axis checks")]
 public static async void Run(){if(!EditorApplication.isPlaying)return;rows.Clear();Save("running");try{
 var go=new GameObject("Focused queued grip controller");go.AddComponent<Rigidbody>().isKinematic=true;var col=go.AddComponent<SphereCollider>();col.isTrigger=true;col.radius=.05f;hand=go.AddComponent<NearFarInteractor>();hand.interactionManager=UnityEngine.Object.FindFirstObjectByType<XRInteractionManager>();hand.enableNearCasting=true;hand.selectInput.inputSourceMode=XRInputButtonReader.InputSourceMode.ManualValue;var attach=hand.interactionAttachController as UnityEngine.XR.Interaction.Toolkit.Attachment.InteractionAttachController;attach.transformToFollow=go.transform;attach.useMomentum=false;attach.useDistanceBasedVelocityScaling=false;attach.useManipulationInput=false;if(hand.farInteractionCaster is CurveInteractionCaster cast){cast.hitDetectionType=CurveInteractionCaster.HitDetectionType.Raycast;cast.castDistance=5;}await Task.Delay(200);
 var s=UnityEngine.Object.FindFirstObjectByType<SweetGame>();s.BeginGame();s.basket.SnapTo(s.rest);s.basketReady=true;await Task.Delay(200);Check("Basket sits on authored inset tray",Mathf.Abs(GameObjectUtility.BoundsOf(s.basket.transform).min.y-1.105f)<.04f,"bottom="+GameObjectUtility.BoundsOf(s.basket.transform).min.y);ChristmasIslandQA.Render("Revision3-Sweet-live",s.rest.position+new Vector3(0,1,2.4f),s.rest.position,75);
 var r=UnityEngine.Object.FindFirstObjectByType<RoutingGame>();r.BeginGame();for(int i=0;i<4;i++)r.Place(i,r.pieces[i]);for(int i=0;i<3;i++)for(int k=0;k<4&&!r.Aligned(i);k++)r.RotatePiece(i);r.Tick();Check("Routing face normal measured in world once",Vector3.Dot(r.socketPlaneNormal,new Vector3(-.1377436f,.58634084f,.79826758f).normalized)>.999f);await Task.Delay(200);var rc=r.sockets[2].transform.position;ChristmasIslandQA.Render("Revision3-Routing-fitted",rc+r.socketPlaneNormal*2.4f,rc,60);
 var d=UnityEngine.Object.FindFirstObjectByType<DiyaGame>();d.BeginGame();foreach(var c in new[]{"drawer","scroll","pot"})d.Credit(c);d.key.SnapTo(d.keySocket,true);d.keyInserted=true;d.SendMessage("SetAccessible");Check("Key docking points toothed end into chest",d.keyTurnAxis==new Vector3(0,0,-1),"axis="+d.keyTurnAxis);ChristmasIslandQA.Render("Revision3-Key-docked",d.keyLockPoint+new Vector3(.4f,.35f,1.3f),d.keyLockPoint,50);d.TurnKey();await Task.Delay(650);Check("Key turns to unlock",d.Step==4);d.OpenChest();await Task.Delay(1400);var chest=GameObjectUtility.FindUnder(GameObjectUtility.FindExact("Diya - Approved Warm Palette"),"Cube.001");Check("Feather rises above open chest",GameObjectUtility.BoundsOf(d.feather.transform).min.y>GameObjectUtility.BoundsOf(chest).max.y+.08f);ChristmasIslandQA.Render("Revision3-Feather-presented",GameObjectUtility.BoundsOf(chest).center+new Vector3(.3f,.9f,1.7f),GameObjectUtility.BoundsOf(d.feather.transform).center,65);
 foreach(var item in new[]{d.feather,d.diya}){if(item==d.diya){d.clean=true;while(d.Step<7)d.Credit("fixture-"+d.Step);d.SendMessage("SetAccessible");}var ok=await Grip(item);Check("Held movement queued grip "+item.itemId,ok);if(ok){var initial=item.transform.position-hand.transform.position;var old=hand.transform.position;for(int i=0;i<10;i++){hand.transform.position=old+new Vector3(i*.04f,0,i*.02f);await Task.Delay(40);}await Task.Delay(150);Check("Held object follows locomotion without scaling "+item.itemId,(item.transform.position-hand.transform.position-initial).magnitude<.15f,"error="+(item.transform.position-hand.transform.position-initial).magnitude);Check("Held object detached from scaled rest "+item.itemId,item.transform.parent==null);}await Release();}
 while(d.Step<9)d.Credit("fixture-final-"+d.Step);d.SendMessage("SetAccessible");await Task.Delay(100);var dp=d.GetComponentInChildren<VenuePanel>();Check("Diya final controls clear of return rest",Vector3.Distance(dp.transform.position,d.diyaRest.position)>1.2f);ChristmasIslandQA.Render("Revision3-Diya-final-panel",d.diyaRest.position+new Vector3(1,1,2),d.diyaRest.position,85);
 var g=UnityEngine.Object.FindFirstObjectByType<RangoliGame>();g.BeginGame();g.ChoosePalette(0);for(int i=0;i<5;i++)g.Place(i,g.pieces[i]);g.RotateSun();await Task.Delay(750);g.SetBrightness(.75f);g.Tick();var pav=GameObjectUtility.FindUnder(GameObjectUtility.FindExact("Rangoli - Approved Warm Palette"),"Cube.002");Check("Pavilion height is human scale",GameObjectUtility.BoundsOf(pav).size.y<5.1f);Check("Display motifs use shallow relief",GameObjectUtility.BoundsOf(g.decorations[1]).size.y<.1f);ChristmasIslandQA.Render("Revision3-Rangoli-live",new Vector3(-22.5f,1.75f,35.7f),new Vector3(-29,1,36),90);
 var f=UnityEngine.Object.FindFirstObjectByType<FireworksGame>();f.BeginGame();f.Load(f.rocket);f.AdjustAim(0);var v0=f.rocket.transform.TransformDirection(f.rocketLocalLaunchAxis);f.AdjustAim(1);var v1=f.rocket.transform.TransformDirection(f.rocketLocalLaunchAxis);Check("Rocket tilts vertically rather than yaw",Mathf.Abs(v0.x-v1.x)<.01f&&Mathf.Abs(v0.y)>.5f&&v0.z*v1.z<0,"axis0="+v0+",axis1="+v1);Check("Launch cannot bypass plunger",!f.Press(0));await Plunge(f,1);f.Load(f.fountain);f.AdjustLift(.5f);await Plunge(f,2);f.Load(f.spinner);f.AdjustSpeed(.6f);await Plunge(f,3);var spin=f.spinnerPivot.rotation;await Task.Delay(3500);Check("Fountain continues beyond old timeout",f.fountainEffect.isPlaying);Check("Spinner keeps rotating",Quaternion.Angle(spin,f.spinnerPivot.rotation)>3);Check("Rocket repeated burst stays running",f.rocketEffect.isPlaying);var fp=f.GetComponentInChildren<VenuePanel>();Check("Firework controls stay on board",Vector3.Distance(fp.transform.position,f.panelPosition)<.02f);ChristmasIslandQA.Render("Revision3-Fireworks-running",new Vector3(0,2.1f,52.5f),new Vector3(0,1.5f,58),85);
 await Release();UnityEngine.Object.Destroy(go);Save("completed");Debug.Log("Focused axis checks completed: "+path);
 }catch(Exception e){Check("Unhandled focused check exception",false,e.ToString());Save("failed");Debug.LogException(e);}}
}
}
